def rules_to_groups(apps, schema_editor):
    """Carry each old rule over: "exactly N from X" becomes a group of X with
    min = max = N questions, "at most N" a group with max N, and "tossup and
    bonus from different members" the category's groups_differ switch."""
    Rule = apps.get_model('qsub', 'DistributionRule')
    Group = apps.get_model('qsub', 'DistributionGroup')
    for rule in Rule.objects.select_related('line'):
        if rule.kind == 'different':
            rule.line.groups_differ = True
            rule.line.save(update_fields=['groups_differ'])
            continue
        Group.objects.create(
            line=rule.line, members=rule.path, sort_order=rule.sort_order,
            min_questions=rule.count if rule.kind == 'exactly' else None,
            max_questions=rule.count)


